#include <MD_MAX72xx.h>
#include <SPI.h>

MD_MAX72XX matrix(MD_MAX72XX::FC16_HW, MATRIX_CS, 1);

int snakeX[64];
int snakeY[64];
int length = 3;
int dx = 1, dy = 0;     // moving right
int foodX, foodY;

void placeFood() {
  foodX = random(0, 8);
  foodY = random(0, 8);
}

void newGame() {
  length = 3;
  for (int i = 0; i < length; i++) {
    snakeX[i] = 3 - i;
    snakeY[i] = 3;
  }
  dx = 1;
  dy = 0;
  placeFood();
}

void setup() {
  matrix.begin();
  matrix.control(MD_MAX72XX::INTENSITY, 2);
  Serial.begin(9600);
  randomSeed(analogRead(0));
  newGame();
}

void loop() {
  // Steer (never straight back into yourself).
  int jx = analogRead(JOY_X_PIN);
  int jy = analogRead(JOY_Y_PIN);
  if (jx < ANALOG_MAX / 4 && dx == 0) { dx = -1; dy = 0; }
  if (jx > ANALOG_MAX * 3 / 4 && dx == 0) { dx = 1; dy = 0; }
  if (jy < ANALOG_MAX / 4 && dy == 0) { dx = 0; dy = -1; }
  if (jy > ANALOG_MAX * 3 / 4 && dy == 0) { dx = 0; dy = 1; }

  // Move: every part takes the place of the one in front.
  int headX = snakeX[0] + dx;
  int headY = snakeY[0] + dy;
  bool crash = headX < 0 || headX > 7 || headY < 0 || headY > 7;
  for (int i = 0; i < length; i++) {
    if (snakeX[i] == headX && snakeY[i] == headY) crash = true;
  }
  if (crash) {
    Serial.print("Game over! Length: ");
    Serial.println(length);
    delay(1500);
    newGame();
    return;
  }
  bool ate = headX == foodX && headY == foodY;
  if (ate && length < 64) length++;
  for (int i = length - 1; i > 0; i--) {
    snakeX[i] = snakeX[i - 1];
    snakeY[i] = snakeY[i - 1];
  }
  snakeX[0] = headX;
  snakeY[0] = headY;
  if (ate) placeFood();

  // Draw.
  matrix.clear();
  for (int i = 0; i < length; i++) {
    matrix.setPoint(snakeY[i], snakeX[i], true);
  }
  matrix.setPoint(foodY, foodX, true);
  delay(250);
}
